component.css:
.ch{position:relative;width:100%;aspect-ratio:1672/941;container-type:size;overflow:hidden;border-radius:10px;background:#000;font-family:"PingFang SC","Microsoft YaHei",sans-serif;user-select:none;-webkit-user-select:none;touch-action:none;cursor:grab}
#chBgm{position:fixed;left:-9999px;top:0;width:2px;height:2px;opacity:0;pointer-events:none}
.ch.is-shake{animation:chShake .34s linear}
@keyframes chShake{0%,100%{transform:none}20%{transform:translate(1.3%,.7%)}40%{transform:translate(-1.1%,.9%)}60%{transform:translate(1%,.5%)}80%{transform:translate(-.9%,-.7%)}}
.ch canvas{position:absolute;inset:0;width:100%;height:100%;display:block;image-rendering:pixelated}
#chMir{left:auto;right:1.8%;top:3%;width:22%;height:22%;border:1px solid rgba(255,120,100,.4);border-radius:4px;background:#000;z-index:3;pointer-events:none}
.ch-vig{position:absolute;inset:0;z-index:2;pointer-events:none;background:radial-gradient(ellipse at 50% 52%,transparent 45%,rgba(20,0,0,.72) 100%)}
.ch-red{position:absolute;inset:0;z-index:6;pointer-events:none;background:radial-gradient(ellipse at 50% 55%,rgba(255,30,10,.1),rgba(190,10,0,.5));opacity:0;transition:opacity .5s}
.ch-bar{position:absolute;left:8%;right:8%;bottom:3.2%;height:1.2cqh;background:rgba(255,255,255,.14);border-radius:1cqh;z-index:4;overflow:hidden}
.ch-bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,#7ce8c8,#4e86b4);border-radius:1cqh}
.ch-wh{position:absolute;left:0;right:0;top:8%;text-align:center;z-index:5;font-size:3.6cqh;letter-spacing:.3em;color:#ffe2dc;text-shadow:0 0 8px #000,0 2px 4px #000;opacity:0;transition:opacity .5s;pointer-events:none}
.ch-wh.is-on{opacity:.95}
.ch-hint{position:absolute;left:0;right:0;bottom:5.6%;text-align:center;z-index:4;font-size:2.2cqh;color:#c9a8a0;opacity:.68;pointer-events:none;text-shadow:0 1px 3px #000}
.ch-pads{position:absolute;right:2.2%;bottom:12%;z-index:5;display:grid;grid-template-columns:repeat(3,8.6cqh);grid-template-rows:repeat(2,8.6cqh);gap:.9cqh}
.ch-pad{border-radius:50%;border:1px solid rgba(255,160,140,.35);background:rgba(38,16,12,.6);color:#ffd9d0;font-size:3.8cqh;line-height:1;display:flex;align-items:center;justify-content:center;padding:0;touch-action:none}
.ch-pad:active{background:rgba(190,80,60,.6)}
.ch-pad--w{grid-column:2;grid-row:1}
.ch-pad--a{grid-column:1;grid-row:2}
.ch-pad--s{grid-column:2;grid-row:2}
.ch-pad--d{grid-column:3;grid-row:2}
.ch-flash{position:absolute;inset:0;z-index:7;pointer-events:none;background:#fff;opacity:0;transition:opacity .9s}
.ch-fr{position:absolute;inset:0;z-index:8;background:#070001;display:flex;align-items:center;justify-content:center;opacity:0;pointer-events:none;transition:opacity .12s}
.ch-fr img{width:82%;filter:contrast(1.4) saturate(1.25) brightness(.92)}
.ch-fr.is-on{opacity:1}
.ch-scare{position:absolute;inset:0;z-index:9;display:none;background:#0a0302;overflow:hidden}
.ch-scare img{width:100%;height:100%;object-fit:cover;filter:contrast(1.3) saturate(1.25);animation:chJit .09s infinite}
.ch-scare.is-on{display:block}
@keyframes chJit{0%{transform:scale(1.05) translate(0,0)}25%{transform:scale(1.08) translate(-1.3%,.9%)}50%{transform:scale(1.06) translate(1%,-.8%)}75%{transform:scale(1.09) translate(-.6%,1.1%)}100%{transform:scale(1.05) translate(.7%,-.5%)}}
.ch-end{position:absolute;inset:0;z-index:10;display:none;background:#000}
.ch-end video{width:100%;height:100%;object-fit:contain}
.ch-card{position:absolute;inset:0;display:none;flex-direction:column;align-items:center;justify-content:center;gap:2.5cqh;background:radial-gradient(ellipse at 50% 45%,#16324a,#050a10 75%)}
.ch-card b{font-size:9cqh;letter-spacing:.5em;color:#cfe8ff;text-shadow:0 0 3cqh #4e86b4}
.ch-card span{font-size:3.2cqh;color:#9fb2c2;letter-spacing:.2em}

component.script:
(() => {
var root=document.getElementById("chRoot"),cv=document.getElementById("chCv"),g=cv.getContext("2d"),mir=document.getElementById("chMir"),mg=mir.getContext("2d"),red=document.getElementById("chRed"),bar=document.getElementById("chBar"),wh=document.getElementById("chWh"),scare=document.getElementById("chScare"),fl=document.getElementById("chFlash"),fr=document.getElementById("chFr"),endv=document.getElementById("chEnd"),vid=document.getElementById("chVid"),card=document.getElementById("chCard"),mon=document.getElementById("chMon"),bgm=document.getElementById("chBgm");
var IW=320,IH=180,MW=96,MH=54;
var SL=String.fromCharCode(47);
var ENDTXT="<EndChat>𝑼𝒏𝒅𝒆𝒓𝒘𝒉𝒆𝒍𝒎𝒆𝒅 𝒃𝒚 𝒕𝒉𝒆 𝒂𝒎𝒃𝒊𝒈𝒖𝒊𝒕𝒚<"+SL+"EndChat>";
var W=2.2,L=420;
var px=0,py=2,ang=1.5708,pitch=0,bobP=0,myy=-16;
var K={w:0,s:0,a:0,d:0,q:0,e:0},velF=0,velS=0;
var gone=false,stUntil=0,lungeUntil=0,nextLunge=14000,nextBeat=0,started=0,stT=0,fc=0,flick=1,whT=null;
var nextFr=9000,blackUntil=0,nextBlk=20000;
var FRT=["它就在你面前。","别回头。","快跑。"];
var clamp=(v,a,b)=>v<a?a:v>b?b:v;
var OB=[],oz=30;
while(oz<L-14){
  var r=Math.random();
  if(r<0.2)OB.push({z:oz,x0:-W,x1:-0.16});
  else if(r<0.4)OB.push({z:oz,x0:0.16,x1:W});
  else if(r<0.54){OB.push({z:oz,x0:-1.32,x1:1.32})}
  else if(r<0.74){OB.push({z:oz,x0:-W,x1:-0.5});OB.push({z:oz,x0:0.5,x1:W})}
  else if(r<0.9){OB.push({z:oz,x0:-W,x1:-0.2});OB.push({z:oz+2.2,x0:0.2,x1:W})}
  else{OB.push({z:oz,x0:-W,x1:-0.9});OB.push({z:oz+1.4,x0:0.9,x1:W});OB.push({z:oz+2.8,x0:-W,x1:-0.2})}
  oz+=12.5+Math.random()*9;
}
var mkc=(w,h)=>{var c=document.createElement("canvas");c.width=w;c.height=h;return c};
var wallC=mkc(64,64),doorC=mkc(64,64),boxC=mkc(64,64);
(function(){
var t=wallC.getContext("2d"),i;
t.fillStyle="#5c4a46";t.fillRect(0,0,64,64);
for(i=0;i<460;i++){t.fillStyle=Math.random()<0.5?"rgba(18,10,8,.2)":"rgba(160,120,110,.13)";t.fillRect(Math.random()*64|0,Math.random()*64|0,2,1)}
for(i=1;i<4;i++){t.fillStyle="#332523";t.fillRect(0,i*16-1,64,2)}
t.fillStyle="#261a18";t.fillRect(0,0,64,3);t.fillRect(0,60,64,4);
t.fillStyle="#705a52";t.fillRect(52,4,7,56);
t.fillStyle="#4a3833";t.fillRect(58,4,1,56);t.fillRect(52,26,7,2);
t.fillStyle="rgba(30,12,8,.45)";t.fillRect(7,36,10,20);t.fillRect(32,20,6,36);
})();
(function(){
var t=boxC.getContext("2d"),i;
t.fillStyle="#57493a";t.fillRect(0,0,64,64);
for(i=0;i<300;i++){t.fillStyle=Math.random()<0.5?"rgba(20,14,8,.22)":"rgba(130,108,82,.14)";t.fillRect(Math.random()*64|0,Math.random()*64|0,3,1)}
t.fillStyle="#2e2620";t.fillRect(0,0,64,4);t.fillRect(0,30,64,4);t.fillRect(0,60,64,4);
t.fillStyle="#3d332a";t.fillRect(0,4,4,60);t.fillRect(60,4,4,60);
t.fillStyle="rgba(95,72,50,.55)";t.fillRect(8,12,10,2);t.fillRect(40,44,12,2);
})();
(function(){
var t=doorC.getContext("2d"),i;
t.fillStyle="#0d1418";t.fillRect(0,0,64,64);
t.fillStyle="#dff2ec";t.fillRect(6,6,52,52);
t.fillStyle="#9fd8ca";t.fillRect(10,10,44,44);
for(i=0;i<60;i++){t.fillStyle="rgba(255,255,255,.5)";t.fillRect(Math.random()*64|0,Math.random()*64|0,1,2)}
})();
var wallD=wallC.getContext("2d").getImageData(0,0,64,64).data;
var doorD=doorC.getContext("2d").getImageData(0,0,64,64).data;
var boxD=boxC.getContext("2d").getImageData(0,0,64,64).data;
var buf=g.createImageData(IW,IH),mbuf=mg.createImageData(MW,MH);
var zb=new Float32Array(IW),mzb=new Float32Array(MW);
var render=(ctx,w,h,img,zb2,dx,dy,cy)=>{
  var dat=img.data,r,c,i;
  var plx=-dy*0.66,ply=dx*0.66;
  var d0x=dx-plx,d0y=dy-ply,d1x=dx+plx,d1y=dy+ply;
  var pz=h*0.5;
  for(r=0;r<h;r++){
    var isF=r>cy,p=isF?r-cy:cy-r;
    if(p<0.5)p=0.5;
    var rd=pz*p**-1;
    var fogF=(1+rd*rd*0.05)**-1;
    var fx=px+rd*d0x,fy=py+rd*d0y;
    var sx=rd*(d1x-d0x)*w**-1,sy=rd*(d1y-d0y)*w**-1;
    var o=r*w*4,br=0.85;
    for(c=0;c<w;c++){
      var gx=fx-Math.floor(fx),gy=fy-Math.floor(fy),e=br,lum=0;
      if(!isF&&gy>0.1&&gy<0.24){e=1.55;lum=1}
      var sh=e*fogF*flick;
      if(lum){dat[o]=255*sh;dat[o+1]=150*sh;dat[o+2]=120*sh}
      else if(sh<0.42){dat[o]=30*sh;dat[o+1]=26*sh;dat[o+2]=24*sh}
      else{dat[o]=62*sh;dat[o+1]=50*sh;dat[o+2]=46*sh}
      dat[o+3]=255;
      fx+=sx;fy+=sy;o+=4;
    }
  }
  for(c=0;c<w;c++){
    var cxr=(2*c)*w**-1-1;
    var rx=dx+plx*cxr,ry=dy+ply*cxr;
    var t=1e9,u=0,td=wallD,sd=0.8,tp,hx,hy;
    if(rx>1e-6){tp=(W-px)*rx**-1;hy=py+ry*tp;if(tp>0&&tp<t&&hy>0&&hy<L){t=tp;u=hy}}
    if(rx<-1e-6){tp=(-W-px)*rx**-1;hy=py+ry*tp;if(tp>0&&tp<t&&hy>0&&hy<L){t=tp;u=hy}}
    if(ry>1e-6){tp=(L-py)*ry**-1;hx=px+rx*tp;if(tp>0&&tp<t&&hx>-W&&hx<W){t=tp;u=hx;td=doorD;sd=1.1}}
    if(ry<-1e-6){tp=(0-py)*ry**-1;hx=px+rx*tp;if(tp>0&&tp<t&&hx>-W&&hx<W){t=tp;u=hx;sd=0.45}}
    for(i=0;i<OB.length;i++){
      var ob=OB[i];
      if(ob.z-py>26||py-ob.z>6)continue;
      if(ry>1e-6||ry<-1e-6){
        tp=(ob.z-py)*ry**-1;
        if(tp>0&&tp<t){hx=px+rx*tp;if(hx>ob.x0&&hx<ob.x1){t=tp;u=hx;td=boxD;sd=0.9}}
      }
    }
    if(t>900)continue;
    zb2[c]=t;
    var half=pz*t**-1;
    var y0=cy-half,y1=cy+half;
    var iy0=Math.max(0,y0|0),iy1=Math.min(h-1,y1|0);
    var tu=((u-Math.floor(u))*64)|0;
    var fs=(1+t*t*0.03)**-1*flick*sd;
    var vs=64*(y1-y0)**-1,tv=(iy0-y0)*vs;
    for(r=iy0;r<=iy1;r++){
      var o=(r*w+c)*4,ti=(((tv|0)&63)*64+tu)*4;
      dat[o]=td[ti]*fs;dat[o+1]=td[ti+1]*fs;dat[o+2]=td[ti+2]*fs;dat[o+3]=255;
      tv+=vs;
    }
  }
  ctx.putImageData(img,0,0);
};
var drawSprite=(ctx,w,h,zb2,dx,dy,cy)=>{
  if(!mon.complete||!mon.naturalWidth)return;
  var plx=-dy*0.66,ply=dx*0.66;
  var sx0=mon.naturalWidth,ih=mon.naturalHeight;
  var rx=0-px,ry=myy-py;
  var det=plx*dy-dx*ply;
  if(Math.abs(det)<1e-9)return;
  var inv=det**-1;
  var tx=inv*(dy*rx-dx*ry),ty=inv*(-ply*rx+plx*ry);
  if(ty<=0.12)return;
  var cxm=(w*0.5)*(1+tx*ty**-1);
  var sh=h*1.15*ty**-1;
  var sw=sh*(sx0*ih**-1);
  var x0=Math.max(0,(cxm-sw*0.5)|0),x1=Math.min(w-1,(cxm+sw*0.5)|0);
  if(x1<x0)return;
  var yTop=cy-sh*0.54,yBot=cy+sh*0.46;
  for(var c=x0;c<=x1;c++){
    if(zb2[c]<ty)continue;
    var tu=((c-(cxm-sw*0.5))*sx0*sw**-1)|0;
    if(tu<0)tu=0;if(tu>=sx0)tu=sx0-1;
    ctx.drawImage(mon,tu,0,1,ih,c,yTop,1,yBot-yTop);
  }
};
var AC=null;
var thump=(v)=>{
  try{
    if(!AC)AC=new(window.AudioContext||window.webkitAudioContext)();
    var o=AC.createOscillator(),gn=AC.createGain();
    o.type="sine";o.frequency.value=54;
    gn.gain.setValueAtTime(v,AC.currentTime);
    gn.gain.exponentialRampToValueAtTime(0.001,AC.currentTime+0.26);
    o.connect(gn);gn.connect(AC.destination);
    o.start();o.stop(AC.currentTime+0.3);
  }catch(e){}
};
var squeal=()=>{
  try{
    if(!AC)AC=new(window.AudioContext||window.webkitAudioContext)();
    var o=AC.createOscillator(),gn=AC.createGain();
    o.type="sawtooth";
    o.frequency.setValueAtTime(1300,AC.currentTime);
    o.frequency.exponentialRampToValueAtTime(160,AC.currentTime+0.42);
    gn.gain.setValueAtTime(0.26,AC.currentTime);
    gn.gain.exponentialRampToValueAtTime(0.001,AC.currentTime+0.46);
    o.connect(gn);gn.connect(AC.destination);
    o.start();o.stop(AC.currentTime+0.5);
  }catch(e){}
};
var whisper=(txt)=>{
  wh.textContent=txt;wh.classList.add("is-on");
  if(whT)clearTimeout(whT);
  whT=setTimeout(()=>wh.classList.remove("is-on"),3000);
};
var caught=()=>{
  if(gone)return;gone=true;
  try{bgm.pause()}catch(e){}
  thump(0.8);scare.classList.add("is-on");
  setTimeout(()=>{
    try{if(typeof changeMsg==="function")changeMsg(ENDTXT)}catch(e){}
  },1300);
};
var showCard=()=>{
  if(card.style.display==="flex")return;
  try{vid.pause()}catch(e){}
  card.style.display="flex";
};
var succeed=()=>{
  if(gone)return;gone=true;
  try{bgm.pause()}catch(e){}
  fl.style.transition="opacity .9s";fl.style.opacity="1";
  setTimeout(()=>{
    endv.style.display="block";
    vid.muted=false;
    var pr=vid.play();
    if(pr&&pr.catch)pr.catch(()=>{
      vid.muted=true;
      var p2=vid.play();
      if(p2&&p2.catch)p2.catch(()=>{});
    });
    vid.addEventListener("ended",showCard);
    vid.addEventListener("error",showCard);
    setTimeout(showCard,90000);
  },950);
};
var startAudio=()=>{
  if(started)return;started=1;
  try{bgm.volume=0.9;var pr=bgm.play();if(pr&&pr.catch)pr.catch(()=>{})}catch(e){}
};
addEventListener("keydown",e=>{
  var k=e.code;
  if(k==="KeyW"||k==="ArrowUp"){K.w=1;e.preventDefault()}
  else if(k==="KeyS"||k==="ArrowDown"){K.s=1;e.preventDefault()}
  else if(k==="KeyA"||k==="ArrowLeft"){K.a=1;e.preventDefault()}
  else if(k==="KeyD"||k==="ArrowRight"){K.d=1;e.preventDefault()}
  else if(k==="KeyQ")K.q=1;
  else if(k==="KeyE")K.e=1;
  startAudio();
});
addEventListener("keyup",e=>{
  var k=e.code;
  if(k==="KeyW"||k==="ArrowUp")K.w=0;
  else if(k==="KeyS"||k==="ArrowDown")K.s=0;
  else if(k==="KeyA"||k==="ArrowLeft")K.a=0;
  else if(k==="KeyD"||k==="ArrowRight")K.d=0;
  else if(k==="KeyQ")K.q=0;
  else if(k==="KeyE")K.e=0;
});
var dragId=null,lx=0,ly=0;
root.addEventListener("pointerdown",e=>{
  startAudio();
  if(e.target.closest(".ch-pad"))return;
  dragId=e.pointerId;lx=e.clientX;ly=e.clientY;
});
addEventListener("pointermove",e=>{
  if(e.pointerId!==dragId)return;
  ang+=(e.clientX-lx)*0.005;
  pitch=clamp(pitch-(e.clientY-ly)*0.45,-32,32);
  lx=e.clientX;ly=e.clientY;
});
addEventListener("pointerup",e=>{if(e.pointerId===dragId)dragId=null});
addEventListener("pointercancel",e=>{if(e.pointerId===dragId)dragId=null});
root.querySelectorAll(".ch-pad").forEach(b=>{
  var k=b.dataset.k;
  b.addEventListener("pointerdown",e=>{e.preventDefault();startAudio();K[k]=1});
  b.addEventListener("pointerup",()=>K[k]=0);
  b.addEventListener("pointerleave",()=>K[k]=0);
  b.addEventListener("pointercancel",()=>K[k]=0);
});
wh.classList.add("is-on");
whT=setTimeout(()=>wh.classList.remove("is-on"),2500);
var frame=(now)=>{
  if(gone)return;
  var dt=Math.min(0.05,(now-stT)*0.001);stT=now;
  var t=now;
  if(K.q)ang-=2.8*dt;
  if(K.e)ang+=2.8*dt;
  var dx=Math.cos(ang),dy=Math.sin(ang);
  var st=t<stUntil;
  var acc=Math.min(1,dt*11);
  velF+=(((st?0:(K.w-K.s))-velF)*acc);
  velS+=((st?0:(K.d-K.a))-velS)*acc;
  var sp=3.6*dt;
  var vx=(velF*dx-velS*dy)*sp;
  var vy=(velF*dy+velS*dx)*sp;
  var oldY=py;
  px=clamp(px+vx,-W+0.25,W-0.25);
  py=clamp(py+vy,0.55,L-0.35);
  if(vy>0){
    for(var i=0;i<OB.length;i++){
      var ob=OB[i];
      if(oldY<ob.z&&py>=ob.z&&px>ob.x0-0.12&&px<ob.x1+0.12){
        py=oldY;stUntil=t+1150;thump(0.55);
        myy=Math.max(myy,py-2.6);
        red.style.opacity="0.62";
        root.classList.remove("is-shake");void root.offsetWidth;root.classList.add("is-shake");
        setTimeout(()=>{red.style.opacity="0"},300);
        whisper("别停下！");
        break;
      }
    }
  }
  var dist=py-myy;
  var ms=3.45,mind=0.75;
  if(t>nextLunge){lungeUntil=t+3000;nextLunge=t+10000+Math.random()*6000;whisper("它加速了——！")}
  if(t<lungeUntil){ms=5.1;mind=0.65}
  if(dist>mind)myy+=ms*dt;
  dist=py-myy;
  if(dist<0.5){caught();return}
  if(py>=L-1.3){succeed();return}
  if(t>nextFr){
    nextFr=t+15000+Math.random()*12000;
    fr.classList.add("is-on");
    squeal();thump(0.85);
    setTimeout(()=>fr.classList.remove("is-on"),240);
    whisper(FRT[Math.random()*FRT.length|0]);
  }
  if(t>nextBlk&&t>stUntil){
    nextBlk=t+24000+Math.random()*14000;
    blackUntil=t+3200;
    whisper("灯——灭了");
  }
  if(t>nextBeat){thump(clamp(0.16+(24-dist)*0.02,0.16,0.5));nextBeat=t+150+Math.max(2,dist)*14}
  bar.style.width=(py*(L-2)**-1*100).toFixed(1)+"%";
  var blk=t<blackUntil?0.06:1;
  flick=(0.82+Math.random()*0.2)*blk;
  var moving=Math.abs(velF)+Math.abs(velS)>0.12;
  if(moving)bobP+=dt*9;
  var cy=IH*0.5+pitch+(moving?Math.sin(bobP)*3:0);
  render(g,IW,IH,buf,zb,dx,dy,cy);
  drawSprite(g,IW,IH,zb,dx,dy,cy);
  if((fc++&1)===0){
    var sv=flick;flick=blk<1?0.55:flick;
    render(mg,MW,MH,mbuf,mzb,-dx,-dy,MH*0.5);
    drawSprite(mg,MW,MH,mzb,-dx,-dy,MH*0.5);
    flick=sv;
  }
  requestAnimationFrame(frame);
};
stT=performance.now();
requestAnimationFrame(frame);
})();
